  #       unzip $src -d $out/bin
  #       chmod +x $out/bin/zed
  #     '';
  #   })
  # ];

  # Add more user-specific configuration as needed
}
```

---

### Step 6: Build and Switch

```sh
sudo nixos-rebuild switch --flake /etc/nixos/flake#my-host
```

---

### Step 7: Login and Enjoy

- Login as your user.
- You should have GNOME on Wayland, all requested apps, and your user environment managed by Home Manager.

---

### Notes

- If `zed` is not in nixpkgs, you need to package it manually as shown above.
