```typescript
import { prisma } from "@/utils/prisma";
import { z } from "zod";
import { FastifyPluginAsyncTypeProvider } from "@/utils/fastify";
import {
  serializerCompiler,
  validatorCompiler,
} from "fastify-type-provider-zod";
import { changePassword } from "@/utils/user";
import { validateAuthUser } from "@/utils/authCheck";
import bcrypt from "bcrypt";

// パスワード更新用のバリデーションスキーマ
const updateUserPasswordSchema = z.object({
  password: z.string(),
  new_password: z.string(),
  new_password_confirmation: z.string(),
});

// bcrypt.compareをPromiseでラップ
function comparePassword(plain: string, hash: string): Promise<boolean> {
  return new Promise((resolve, reject) => {
    bcrypt.compare(plain, hash, (err, result) => {
      if (err) return reject(err);
      resolve(result);
    });
  });
}

// パスワードバリデーション
function validateNewPasswords(
  current: string,
  next: string,
  confirm: string
): string | null {
  if (current === next) {
    return "新しいパスワードは現在のパスワードと違うものを入力してください";
  }
  if (next !== confirm) {
    return "新しいパスワードが一致しません";
  }
  return null;
}

const updateUserPassword: FastifyPluginAsyncTypeProvider = async (fastify) => {
  fastify.setSerializerCompiler(serializerCompiler);
  fastify.setValidatorCompiler(validatorCompiler);

  fastify.patch(
    "/",
    {
      schema: {
        body: updateUserPasswordSchema,
      },
    },
    async (request, reply) => {
      // 認証ユーザー取得
      const authUser = validateAuthUser(request.user);

      // ユーザー情報取得
      const user = await prisma.users.findUnique({
        where: { id: authUser.id },
      });
      if (!user) {
        throw fastify.httpErrors.notFound("ユーザー情報がありません");
      }

