    let player: String
    let detail: PointDetail?
    let timestamp: Date
}

struct SetScore {
    var gamesP1: Int = 0
    var gamesP2: Int = 0
}

class Match: ObservableObject {
    @Published var sets: [SetScore] = [SetScore(), SetScore(), SetScore()]
    @Published var currentSet: Int = 0
    @Published var points: [Point] = []
    @Published var advancedMode: Bool = false
    @Published var gamePointsP1: Int = 0
    @Published var gamePointsP2: Int = 0

    func addPoint(player: String, detail: PointDetail? = nil) {
        points.append(Point(player: player, detail: detail, timestamp: Date()))
        if player == "Player 1" {
            gamePointsP1 += 1
        } else {
            gamePointsP2 += 1
        }
        checkGameOver()
    }

    func checkGameOver() {
        // Simple tennis scoring: 0, 15, 30, 40, Advantage, Game
        // For brevity, this is simplified and does not handle all edge cases (like deuce/advantage)
        if gamePointsP1 >= 4 && gamePointsP1 - gamePointsP2 >= 2 {
            sets[currentSet].gamesP1 += 1
            gamePointsP1 = 0
            gamePointsP2 = 0
            checkSetOver()
        } else if gamePointsP2 >= 4 && gamePointsP2 - gamePointsP1 >= 2 {
            sets[currentSet].gamesP2 += 1
            gamePointsP1 = 0
            gamePointsP2 = 0
            checkSetOver()
        }
    }

    func checkSetOver() {
        let p1 = sets[currentSet].gamesP1
        let p2 = sets[currentSet].gamesP2
        if (p1 >= 6 || p2 >= 6) && abs(p1 - p2) >= 2 {
            if currentSet < 2 {
                currentSet += 1
            }
        }
    }

    func reset() {
        sets = [SetScore(), SetScore(), SetScore()]
        currentSet = 0
        points = []
        gamePointsP1 = 0
        gamePointsP2 = 0
    }

    func gameScoreString() -> String {
        func scoreString(_ pts: Int) -> String {
            switch pts {
            case 0: return "0"
            case 1: return "15"
            case 2: return "30"
            case 3: return "40"
            default: return "Ad"
            }
        }
        if gamePointsP1 >= 3 && gamePointsP2 >= 3 {
            if gamePointsP1 == gamePointsP2 {
                return "Deuce"
            } else if gamePointsP1 > gamePointsP2 {
                return "Ad Player 1"
            } else {
                return "Ad Player 2"
            }
        }
        return "\(scoreString(gamePointsP1)) - \(scoreString(gamePointsP2))"
    }
}

