      let code = editor.value.replace(/\t/g,'  ');
      if(lang==='js'){
        code = code.replace(/(\/\/.*|\/\*[\s\S]*?\*\/)/g, '<span class="token comment">$1</span>');
        code = code.replace(/(["'`])(?:\\.|(?!\1).)*\1/g, '<span class="token string">$&</span>');
        code = code.replace(/\b(function|return|var|let|const|if|else|for|while|break|continue|switch|case|default|throw|try|catch|finally|new|this|typeof|instanceof|in|of|await|async|class|extends|super|import|from|export)\b/g, '<span class="token keyword">$1</span>');
