          p2 = p2.replace(/([a-zA-Z\-:]+)(=)("[^"]*"|'[^']*')/g, '<span class="token attr">$1</span>$2<span class="token attrval">$3</span>');
          return '<span class="token tag">'+p1+'</span>'+p2+'<span class="token tag">'+p3+'</span>';
        });
      } else if(lang==='css'){
        code = code.replace(/(\/\*[\s\S]*?\*\/)/g, '<span class="token comment">$1</span>');
        code = code.replace(/([.#]?[a-zA-Z0-9_-]+)(\s*\{)/g, '<span class="token keyword">$1</span>$2');
        code = code.replace(/(["'])(?:\\.|(?!\1).)*\1/g, '<span class="token string">$&</span>');
        code = code.replace(/\b\d+(\.\d+)?(px|em|rem|%)?\b/g, '<span class="token number">$&</span>');
      } else {
        code = code.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
      }
      highlight.innerHTML = code;
    }
    function updateLines(){
      const lines = editor.value.split('\n').length;
      lineNumbers.innerHTML = Array.from({length:lines},(_,i)=>i+1).join('\n');
    }
    function updateCursor(){
      const pos = editor.selectionStart;
      const lines = editor.value.substr(0,pos).split('\n');
      cursorPos.textContent = `Ln ${lines.length}, Col ${lines[lines.length-1].length+1}`;
    }
    function updateCount(){
      const words = (editor.value.match(/\b\w+\b/g)||[]).length;
      countInfo.textContent = `Words: ${words} | Chars: ${editor.value.length}`;
    }
    function saveFile(){
      const blob = new Blob([editor.value], {type:'text/plain'});
      const a = document.createElement('a');
      a.href = URL.createObjectURL(blob);
      let ext = lang==='js'?'.js':lang==='html'?'.html':lang==='css'?'.css':'.txt';
      a.download = 'note'+ext;
      a.click();
      URL.revokeObjectURL(a.href);
    }
    // Find/Replace
    function showFind(){
      findBar.style.display = 'flex';
      findInput.focus();
      findAll();
    }
    function findAll(){
      const val = editor.value, q = findInput.value;
      findMatches = [];
      if(!q) return;
      let idx = 0;
      while((idx = val.indexOf(q, idx))!==-1){
        findMatches.push(idx);
        idx += q.length;
      }
      findIdx = -1;
    }
    function findNext(){
      if(!findMatches.length) return;
      findIdx = (findIdx+1)%findMatches.length;
      const idx = findMatches[findIdx];
      editor.focus();
      editor.selectionStart = idx;
      editor.selectionEnd = idx+findInput.value.length;
    }
    function doReplace(){
      if(findIdx<0||!findMatches.length) return;
      const idx = findMatches[findIdx];
      const before = editor.value.slice(0,idx);
      const after = editor.value.slice(idx+findInput.value.length);
      editor.value = before+replaceInput.value+after;
      updateAll();
      findAll();
    }
