    http
        .requestMatcher(new RequestHeaderRequestMatcher("Referer", "https://refererB.com"))
        .addFilterBefore(new FilterForRefererB(), UsernamePasswordAuthenticationFilter.class)
        .authorizeRequests().anyRequest().authenticated();
    return http.build();
}

@Bean
