#include <QCoreApplication>
#include <QDebug>
#include <QSet>
#include <QVariant>
#include <QString>
#include "xlsxdocument.h"

bool parseCellToInt(const QVariant &cellValue, int &result) {
    bool ok = false;

    // If the cell is numeric, check if it's an integer
    if (cellValue.canConvert<double>()) {
        double d = cellValue.toDouble();
        int i = static_cast<int>(d);
        if (qFuzzyCompare(d + 1.0, i + 1.0)) {
            result = i;
            return true;
        }
    }

    // If the cell is a string, parse possible formats
    QString s = cellValue.toString().trimmed().toLower();

    // Hexadecimal: 0x2a or 2ah
    if (s.startsWith("0x")) {
        result = s.mid(2).toInt(&ok, 16);
        if (ok) return true;
    }
    if (s.endsWith("h")) {
        result = s.left(s.length() - 1).toInt(&ok, 16);
        if (ok) return true;
    }
    // Binary: 0b101010 or b101010
    if (s.startsWith("0b")) {
        result = s.mid(2).toInt(&ok, 2);
        if (ok) return true;
    }
    if (s.startsWith("b")) {
        result = s.mid(1).toInt(&ok, 2);
        if (ok) return true;
    }
    // Octal: 0o52 or 052
    if (s.startsWith("0o")) {
        result = s.mid(2).toInt(&ok, 8);
        if (ok) return true;
    }
    if (s.startsWith("0") && s.length() > 1 && s.indexOf(QRegExp("[^0-7]")) == -1) {
        result = s.toInt(&ok, 8);
        if (ok) return true;
    }
    // Decimal
    result = s.toInt(&ok, 10);
    if (ok) return true;

    // Try as double and check if integer
    double d = s.toDouble(&ok);
    if (ok) {
        int i = static_cast<int>(d);
        if (qFuzzyCompare(d + 1.0, i + 1.0)) {
            result = i;
            return true;
        }
    }
    return false;
}

int main(int argc, char *argv[]) {
    QCoreApplication a(argc, argv);

    QString filePath = "file.xlsx";
    QString cellRef = "A1";

    QXlsx::Document xlsx(filePath);
    if (!xlsx.load()) {
        qWarning() << "Failed to load file";
        return -1;
