**Prompt Recap:**  
Write code for a geometry shader in Unity that samples a texture with transparency.  
1. Create a quad for each pixel that is not transparent  
2. Extrude each quad by a factor

---

**My Answer:**

To achieve this in Unity, you need a geometry shader that receives a mesh of points (one per pixel), samples a texture at each point's UV, and emits a quad (two triangles) for each non-transparent pixel, extruding the quad along a direction by a given factor.

**Shader Code:**

```hlsl
Shader "Custom/ExtrudedTextureQuads"
{
    Properties
    {
        _MainTex ("Texture", 2D) = "white" {}
        _Extrude ("Extrude Factor", Float) = 0.1
        _AlphaThreshold ("Alpha Threshold", Range(0,1)) = 0.1
    }
    SubShader
    {
        Tags { "RenderType"="Opaque" }
        Pass
        {
            CGPROGRAM
            #pragma vertex vert
            #pragma geometry geom
            #pragma fragment frag
            #pragma target 4.0

            #include "UnityCG.cginc"

            sampler2D _MainTex;
            float _Extrude;
            float _AlphaThreshold;
            float4 _MainTex_TexelSize;

            struct appdata
            {
                float3 vertex : POSITION;
                float2 uv : TEXCOORD0;
            };

            struct v2g
            {
                float4 vertex : POSITION;
                float2 uv : TEXCOORD0;
            };

            struct g2f
            {
                float4 vertex : SV_POSITION;
                float2 uv : TEXCOORD0;
            };

            v2g vert(appdata v)
            {
                v2g o;
                o.vertex = UnityObjectToClipPos(float4(v.vertex, 1.0));
                o.uv = v.uv;
                return o;
            }

            [maxvertexcount(6)]
            void geom(point v2g IN[1], inout TriangleStream<g2f> triStream)
            {
                float4 col = tex2D(_MainTex, IN[0].uv);
                if (col.a < _AlphaThreshold)
                    return;

                // Calculate quad size in clip space (could use _MainTex_TexelSize for accuracy)
                float2 pixelOffset = float2(_MainTex_TexelSize.x, _MainTex_TexelSize.y) * 0.5;

                float4 basePos = IN[0].vertex;
                float4 offsets[4] = {
                    float4(-pixelOffset.x, -pixelOffset.y, 0, 0), // BL
                    float4( pixelOffset.x, -pixelOffset.y, 0, 0), // BR
                    float4( pixelOffset.x,  pixelOffset.y, _Extrude, 0), // TR (extruded)
                    float4(-pixelOffset.x,  pixelOffset.y, _Extrude, 0)  // TL (extruded)
                };

                g2f o;

                // First triangle
                o.vertex = basePos + offsets[0]; o.uv = IN[0].uv; triStream.Append(o);
                o.vertex = basePos + offsets[1]; o.uv = IN[0].uv; triStream.Append(o);
                o.vertex = basePos + offsets[2]; o.uv = IN[0].uv; triStream.Append(o);

                // Second triangle
                o.vertex = basePos + offsets[2]; o.uv = IN[0].uv; triStream.Append(o);
                o.vertex = basePos + offsets[3]; o.uv = IN[0].uv; triStream.Append(o);
                o.vertex = basePos + offsets[0]; o.uv = IN[0].uv; triStream.Append(o);
            }

            fixed4 frag(g2f i) : SV_Target
            {
                fixed4 col = tex2D(_MainTex, i.uv);
                clip(col.a - _AlphaThreshold);
                return col;
            }
            ENDCG
        }
    }
    FallBack "Diffuse"
}
```

**Usage Notes:**
