<?php

namespace Drupal\my_module\Plugin\Block;

use Drupal\Core\Block\BlockBase;
use Drupal\Core\Entity\EntityTypeManagerInterface;
use Symfony\Component\DependencyInjection\ContainerInterface;
use Drupal\Core\Plugin\ContainerFactoryPluginInterface;

/**
 * Provides a block listing article teasers tagged with 'foobar'.
 *
 * @Block(
 *   id = "article_foobar_teaser_block",
 *   admin_label = @Translation("Article Teasers Tagged 'foobar'")
 * )
 */
class ArticleFoobarTeaserBlock extends BlockBase implements ContainerFactoryPluginInterface {

  /**
   * The entity type manager.
   *
   * @var \Drupal\Core\Entity\EntityTypeManagerInterface
   */
  protected $entityTypeManager;

  /**
   * Constructs a new ArticleFoobarTeaserBlock.
   */
  public function __construct(array $configuration, $plugin_id, $plugin_definition, EntityTypeManagerInterface $entity_type_manager) {
    parent::__construct($configuration, $plugin_id, $plugin_definition);
    $this->entityTypeManager = $entity_type_manager;
  }

  /**
   * {@inheritdoc}
   */
  public static function create(ContainerInterface $container, array $configuration, $plugin_id, $plugin_definition) {
    return new static(
      $configuration,
      $plugin_id,
      $plugin_definition,
      $container->get('entity_type.manager')
    );
  }

  /**
   * {@inheritdoc}
   */
  public function build() {
    // Load the taxonomy term 'foobar' from the 'tags' vocabulary.
    $term_storage = $this->entityTypeManager->getStorage('taxonomy_term');
    $terms = $term_storage->loadByProperties([
      'name' => 'foobar',
      'vid' => 'tags', // Adjust if your vocabulary is different.
    ]);
    $term = $terms ? reset($terms) : NULL;

    if (!$term) {
      return [
        '#markup' => $this->t('No articles found with the tag "foobar".'),
      ];
    }

    // Query for published article nodes tagged with this term.
    $query = $this->entityTypeManager->getStorage('node')->getQuery()
      ->condition('type', 'article')
      ->condition('status', 1)
      ->condition('field_tags', $term->id())
      ->sort('created', 'DESC')
      ->range(0, 5);

    $nids = $query->execute();

    if (empty($nids)) {
      return [
        '#markup' => $this->t('No articles found with the tag "foobar".'),
      ];
    }

    $nodes = $this->entityTypeManager->getStorage('node')->loadMultiple($nids);
    $view_builder = $this->entityTypeManager->getViewBuilder('node');

    $items = [];
    foreach ($nodes as $node) {
      $items[] = $view_builder->view($node, 'teaser');
    }

    // Render as Bootstrap 5 list group.
    return [
      '#theme' => 'item_list',
      '#items' => $items,
      '#attributes' => ['class' => ['list-group']],
      '#cache' => [
        'tags' => ['node_list', 'taxonomy_term:' . $term->id()],
      ],
    ];
  }
}
```

